# Expected values are SymPy's outputs for the same calls (Formal power series arithmetic, bell and normal forms).

skip_unless_full_tests()

skip_on_cran()

x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); n <- Symbol("n", integer = TRUE)

test_that("Formal power series arithmetic, bell and normal forms match SymPy", {
  expect_equal(sstr(fps_product(fps(sin(x)), fps(exp(x)), n = 6)), "FormalPowerSeriesProduct(FormalPowerSeries(sin(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2 - 1/2)/(RisingFactorial(3/2, _k/2 - 1/2)*factorial(_k/2 - 1/2)), Eq(Mod(_k, 2), 1)), (0, True)), (_k, 2, oo)), SeqFormula(x^_k, (_k, 0, oo)), x)), FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_truncate(fps_product(fps(sin(x)), fps(exp(x))), 6)), "x + x^2 + x^3/3 - x^5/30 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps_compose(fps(exp(x)), fps(sin(x))), 6)), "1 + x + x^2/2 - x^4/8 - x^5/15 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps_compose(fps(exp(x)), fps(sin(x))), 4)), "1 + x + x^2/2 + O(x^4)")
  expect_equal(sstr(fps_truncate(fps_compose(fps(cos(x)), fps(sin(x))), 8)), "1 - x^2/2 + 5*x^4/24 - 37*x^6/720 + O(x^8)")
  expect_equal(sstr(fps_truncate(fps_inverse(fps(exp(x))), 6)), "1 - x + x^2/2 - x^3/6 + x^4/24 - x^5/120 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps_inverse(fps(cos(x))), 8)), "1 + x^2/2 + 5*x^4/24 + 61*x^6/720 + O(x^8)")
  expect_equal(sstr(fps_truncate(fps_product(fps(exp(x)), fps(cos(x))), 4)), "1 + x - x^3/3 + O(x^4)")
  expect_equal(sstr(bell(5)), "52")
  expect_equal(sstr(bell(5, x)), "x^5 + 10*x^4 + 25*x^3 + 15*x^2 + x")
  expect_equal(sstr(bell(0, x)), "1")
  expect_equal(sstr(bell(n)), "bell(n)")
  expect_equal(sstr(bell(oo)), "oo")
  expect_equal(sstr(fps_product(fps(exp(x)), fps(cos(x)), n = 4)), "FormalPowerSeriesProduct(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)), FormalPowerSeries(cos(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2)/(RisingFactorial(1/2, _k/2)*factorial(_k/2)), Eq(Mod(_k, 2), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_compose(fps(exp(x)), fps(sin(x)), n = 6)), "FormalPowerSeriesCompose(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)), FormalPowerSeries(sin(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2 - 1/2)/(RisingFactorial(3/2, _k/2 - 1/2)*factorial(_k/2 - 1/2)), Eq(Mod(_k, 2), 1)), (0, True)), (_k, 2, oo)), SeqFormula(x^_k, (_k, 0, oo)), x)))")
  expect_equal(sstr(fps_compose(fps(exp(x)), fps(sin(x)), n = 4)), "FormalPowerSeriesCompose(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)), FormalPowerSeries(sin(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2 - 1/2)/(RisingFactorial(3/2, _k/2 - 1/2)*factorial(_k/2 - 1/2)), Eq(Mod(_k, 2), 1)), (0, True)), (_k, 2, oo)), SeqFormula(x^_k, (_k, 0, oo)), x)))")
  expect_equal(sstr(fps_compose(fps(cos(x)), fps(sin(x)), n = 6)), "FormalPowerSeriesCompose(FormalPowerSeries(cos(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2)/(RisingFactorial(1/2, _k/2)*factorial(_k/2)), Eq(Mod(_k, 2), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)), FormalPowerSeries(sin(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2 - 1/2)/(RisingFactorial(3/2, _k/2 - 1/2)*factorial(_k/2 - 1/2)), Eq(Mod(_k, 2), 1)), (0, True)), (_k, 2, oo)), SeqFormula(x^_k, (_k, 0, oo)), x)))")
  expect_equal(sstr(fps_inverse(fps(exp(x)), n = 6)), "FormalPowerSeriesInverse(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_inverse(fps(cos(x)), n = 6)), "FormalPowerSeriesInverse(FormalPowerSeries(cos(x), x, 0, 1, (SeqFormula(Piecewise(((-1/4)^(_k/2)/(RisingFactorial(1/2, _k/2)*factorial(_k/2)), Eq(Mod(_k, 2), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_inverse(fps(exp(x)), n = 4)), "FormalPowerSeriesInverse(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_truncate(fps_integrate(fps(sin(x))))), "-1 + x^2/2 - x^4/24 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps_integrate(fps(exp(x))))), "1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120 + O(x^6)")
  expect_equal(sstr(fps_truncate(diff(fps(sin(x)), x))), "1 - x^2/2 + x^4/24 + O(x^6)")
  expect_equal(sstr(fps_truncate(diff(fps(exp(x)), x))), "1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps(sin(x)) + fps(exp(x)))), "1 + 2*x + x^2/2 + x^4/24 + x^5/60 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps(exp(x)) - fps(cos(x)))), "x + x^2 + x^3/6 + x^5/120 + O(x^6)")
  expect_equal(sstr(fps_truncate(-fps(sin(x)))), "-x + x^3/6 - x^5/120 + O(x^6)")
  expect_equal(sstr(fps_truncate(2 * fps(sin(x)))), "2*x - x^3/3 + x^5/60 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps(sin(x)) * 3)), "3*x - x^3/2 + x^5/40 + O(x^6)")
  expect_equal(sstr(fps_truncate(fps(exp(x)) + 1)), "2 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120 + O(x^6)")
  expect_equal(sstr(fps_product(fps(exp(x)), fps(exp(x)), n = 5)), "FormalPowerSeriesProduct(FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)), FormalPowerSeries(exp(x), x, 0, 1, (SeqFormula(Piecewise((1/factorial(_k), Eq(Mod(_k, 1), 0)), (0, True)), (_k, 1, oo)), SeqFormula(x^_k, (_k, 0, oo)), 1)))")
  expect_equal(sstr(fps_truncate(fps_integrate(fps(log(1 + x))))), "x^2/2 - x^3/6 + x^4/12 - x^5/20 + O(x^6)")
  expect_equal(sstr(fps_truncate(diff(fps(atan(x)), x))), "1 - x^2 + x^4 + O(x^6)")
  expect_equal(sstr(bell(6, 2, symbols("x:7"))), "6*x0*x4 + 15*x1*x3 + 10*x2^2")
  expect_equal(sstr(bell(4, 2, list(x, y, z))), "4*x*z + 3*y^2")
  expect_equal(sstr(hermite_normal_form(Matrix(list(list(2, 7, 17, 29, 41), list(3, 11, 19, 31, 43), list(5, 13, 23, 37, 47))))), "Matrix([[1, 0, 0], [0, 2, 1], [0, 0, 1]])")
  expect_equal(sstr(hermite_normal_form(Matrix(list(list(2, 7), list(0, 0), list(0, 0))))), "Matrix([[1], [0], [0]])")
  expect_equal(sstr(hermite_normal_form(Matrix(list(list(-2, 1), list(0, 1))))), "Matrix([[2, 1], [0, 1]])")
  expect_equal(sstr(hermite_normal_form(Matrix(list(list(0, 0, 0), list(0, 0, 0), list(1, 0, 0))))), "Matrix([[0], [0], [1]])")
  expect_equal(sstr(hermite_normal_form(Matrix(list(list(8, 2, 5), list(0, 7, 1), list(3, 4, 6))), D = 336)), "Matrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]])")
  expect_equal(sstr(smith_normal_form(Matrix(list(list(12, 6, 4), list(3, 9, 6), list(2, 16, 14))))), "Matrix([[1, 0, 0], [0, 10, 0], [0, 0, 30]])")
  expect_equal(sstr(smith_normal_form(Matrix(list(list(2, 4, 4), list(-6, 6, 12), list(10, -4, -16))))), "Matrix([[2, 0, 0], [0, 6, 0], [0, 0, 12]])")
  expect_equal(sstr(smith_normal_form(Matrix(list(list(6, -2), list(5, 3))))), "Matrix([[1, 0], [0, 28]])")
  expect_equal(sstr(smith_normal_form(Matrix(list(list(0, 0), list(0, 0))))), "Matrix([[0, 0], [0, 0]])")
  expect_equal(sstr(smith_normal_form(Matrix(list(list(1, 2, 3), list(4, 5, 6))))), "Matrix([[1, 0, 0], [0, 3, 0]])")
  expect_equal(sstr(invariant_factors(Matrix(list(list(12, 6, 4), list(3, 9, 6), list(2, 16, 14))))), "(1, 10, 30)")
  expect_equal(sstr(invariant_factors(Matrix(list(list(2, 4, 4), list(-6, 6, 12), list(10, -4, -16))))), "(2, 6, 12)")
  expect_error(fps_compose(fps(sin(x)), fps(exp(x))), "The formal power series of the inner function should not have any constant coefficient term.", fixed = TRUE)
  expect_error(fps_truncate(fps(sin(x)) + x), "'Add' object has no attribute 'truncate'", fixed = TRUE)
})
